package org.eclipse.rdf4j.sail.lmdb.benchmark;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.benchmark.LmdbNativeRegretHarness.Regret;
import org.eclipse.rdf4j.sail.lmdb.benchmark.LmdbNativeRegretHarness.Timing;
import org.junit.jupiter.api.Test;

class LmdbNativeRegretHarnessEdgeCaseTest {

	@Test
	void timedOutChosenStrategyMustNotDisappearWhenARivalCompletes() {
		Timing chosen = timing("nestedLoop", true, Double.NaN, -1L, "failed: Query evaluation took too long");
		Timing rival = timing("irKernel", false, 100_000D, 12L, "");

		List<Regret> regrets = LmdbNativeRegretHarness.regrets(List.of(chosen, rival));

		assertThat(regrets).as("A failed selector choice cannot be silently excluded from the acceptance gate")
				.hasSize(1);
		assertThat(regrets.get(0).chosen()).isEqualTo(chosen);
		assertThat(regrets.get(0).fastest()).isEqualTo(rival);
		assertThat(regrets.get(0).ratio()).isEqualTo(Double.POSITIVE_INFINITY);
	}

	@Test
	void aDeclinedRivalDoesNotInvalidateACompletedChoice() {
		Timing chosen = timing("nestedLoop", true, 200_000D, 12L, "");
		Timing rival = timing("irKernel", false, Double.NaN, -1L, "declined: unavailable");

		List<Regret> regrets = LmdbNativeRegretHarness.regrets(List.of(chosen, rival));

		assertThat(regrets).hasSize(1);
		assertThat(regrets.get(0).fastest()).isEqualTo(chosen);
		assertThat(regrets.get(0).ratio()).isEqualTo(1D);
	}

	private static Timing timing(String strategy, boolean chosen, double nanos, long rows, String note) {
		return new Timing("query", "spoc,posc", "lmdbOnly", "row/join dispatch", strategy, chosen, true,
				nanos, nanos, rows, 100_000D, 50_000D, 200_000D, null, note);
	}
}
